/**
 * Badge displayed on the button. To clear the badge, set to empty string or
 * nullish value.
 *
 * @type {string}
 */
set badge(badgeText) {
  if (badgeText === "" || badgeText == null) {
    this.removeAttribute("badge");
    return;
  }
  this.setAttribute("badge", badgeText);
}

get badge() {
  return this.getAttribute("badge");
}
